"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[97e3],{44026:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[],"name":"ShredderResultCodes","desc":"Frozen enum-style table of integer result codes shared by `ShredderServer`\\nand any client code that interprets shredder outcomes.\\n\\nThe table is `table.freeze`d \u2014 treat it as read-only at all times.\\n\\n### Codes\\n\\n| Name | Value | Meaning |\\n|------|-------|---------|\\n| `NONE` | `0` | No result / default unset state. |\\n| `INVALID_WORKBENCH` | `1` | The target workbench does not exist or is not a valid shredder. |\\n| `TOO_FAR` | `2` | The player is too far from the workbench. |\\n| `WORKBENCH_BUSY` | `3` | Another session is already active on this workbench. |\\n| `COOLDOWN` | `4` | The workbench is on cooldown from a previous shred. |\\n| `NO_JUNK` | `5` | The player has no junk items to shred. |\\n| `NO_SESSION` | `6` | No active shredding session exists (hold-complete arrived with no matching session). |\\n| `SESSION_MISMATCH` | `7` | The session token sent by the client does not match the server session. |\\n| `HOLD_TOO_SHORT` | `8` | The player released the hold before the required duration elapsed. |\\n| `NO_MATERIAL_OUTPUT` | `9` | The shred succeeded but produced no material (e.g. empty loot table). |","source":{"line":28,"path":"src/ReplicatedStorage/SharedModules/ShredderResultCodes.luau"}}')}}]);